  const prompt=`Use case: precise-object-edit. Edit ONLY the crystal details on the entire original ${skin} ${weapon} WHITE-FORM COMBAT SHEET. Input1 = complete EDIT TARGET; Input2 = reference ONLY for WHITE/SILVER FACETED CRYSTAL SHARDS at shoulders and wrist cuffs. Do not copy Input2 walking poses, scale, face, body or layout. Canvas and layout MUST remain exactly 1024x1536, FOUR COLUMNS by SIX ROWS, EXACTLY the same TWENTY-FOUR whole poses in identical order and positions. Change only existing shoulder/cuff stud areas into small but visibly protruding physical white/silver faceted crystals matching Input2. Gray facet borders and restrained pearl highlights make them readable, projecting slightly outside the shoulder/cuff silhouette. Use the same crystal material consistently across all 24 poses, with correct occlusion and perspective. Do not draw a crystal over a hand, face, blade or occluded arm. ${outfit} ${equipment} Freeze and preserve every original HEAD, FACE, CROWN SIZE, TORSO WIDTH, WAIST, SKIN, ARM/LEG LENGTH, MUSCLES, FINGERS, BOOT SIZE, BOOT TOE DIRECTION, pose and silhouette outside the tiny crystal additions. NO head or torso redesign, no normalization, no shrinking, no rescaling individual poses, no body-part assembly or cropped-element compositing. Preserve the existing approved long silver-white wavy hair exactly, including rear tufts to upper back in side/turned poses; never shorten it to nape and never extend to waist. Original warm peach human skin and red irises remain unchanged and neutrally lit; no white/neon/orange spill on skin. Weapons and all cores stay white/silver, never red/pink/violet. ${merged?"The source has two existing figures connected by their overlapping pixels; preserve every whole figure at its exact source position and preserve the existing contact. Do NOT separate, relocate, delete, duplicate or invent poses to force a component count.":""} Preserve all hands, fingers, feet, facial identity, coat or vest shapes, every weapon and original gutters/border margins. No new VFX, aura, glow, afterimages, shadows, labels, grid, text or watermark. True transparent alpha0 background, keep opaque black clothing and crisp source game-raster contours. Return the entire unchanged-layout 24-pose sheet, with ONLY the physical white crystal spikes added.`;
  return {file,skin,weapon,prompt,inputs:[base+file,base+skin+"-frontal-grande-branca-cristais-v2.png"],expectedSize:[1024,1536],selected:false};
});
store("combo_cristais_jobs",jobs);text({jobs:jobs.length,mode:"integrated whole-sheet edits",selected:false});
// @exec: {"yield_time_ms": 120000, "max_output_tokens": 1500}
const jobs=load("combo_cristais_ready");
const corrections=jobs.filter(j=>["Requiem-katana-combo-branca.png","Rock-adagas-combo-branca.png","Rock-corrente-combo-branca.png"].includes(j.file)).map(job=>{
  const tip=job.file.startsWith("Requiem")?"One clear error to fix: pose19 (zero based, fifth row fourth column) has its katana tip touching the RIGHT canvas edge around x1023,y1234. Restore the exact original complete pose/weapon position and length from input2 so the entire blade tip has the original transparent margin, without shrinking any body or weapon. Keep head, torso, limbs, pose and all white crystals exactly as input1. Also keep the background genuinely transparent alpha0.":"One clear error to fix: the gray/brown empty background of input1 has nonzero alpha and connects multiple poses. Remove ONLY this background/veil and make all empty gutters and outer margins genuinely alpha0. Preserve every opaque original sprite pixel, white hair, warm peach skin, black clothing, silver weapons, white crystal spikes, all hands/boots and the precise24poses, body dimensions and placement. Keep opaque black clothing intact; do not remove dark sprite colors.";
  const prompt=`Use case: precise-object-edit. Input1 is the entire 1024x1536 24-pose complete crystal-edited sheet to correct. Input2 is the complete original sheet, reference ONLY for original margins, layout and preserved characters. ${tip} STRICT: preserve FOUR columns SIX rows, all TWENTY-FOUR complete source poses in identical order. Do not redesign, re-pose, normalize, scale, crop, disassemble, copy/paste parts, split merged source figures, duplicate or omit any character. This is one targeted correction of the ENTIRE sheet. Preserve all added white/silver faceted crystals at shoulders/cuffs, unchanged white upper-back hair length, skin and original ${job.skin} outfit. No new effects, neon, shadow, text/grid or painted checkerboard. Output true transparent RGBA with empty alpha0 background, complete uncut figures and original pixel dimensions.`;
  return {...job,correctionPrompt:prompt};
});
store("combo_cristais_corrections",corrections);
const results=await Promise.allSettled(corrections.map(async job=>{
  const result=await tools.image_gen__imagegen({prompt:job.correctionPrompt,referenced_image_paths:[job.generatedSource,job.inputs[0]],transparent_background:true});
  const path=result.output_hint?.match(/ as (C:\\[^\n]+\.png) by default/)?.[1]??null;
  store("combo_cristais_corrected_"+job.file,{result,path,prompt:job.correctionPrompt});
  generatedImage(result);notify({file:job.file,correctionComplete:true,path});return {file:job.file,path};
}));
text(results.map((r,i)=>r.status==="fulfilled"?r.value:{file:corrections[i].file,error:String(r.reason)}));
